try {
  helpers.log('Starting HTTP Request node');

  const fetch = (await import('node-fetch')).default;
  let url = node.properties.url.value;
  const method = node.properties.method.value;
  const bodyValue = node.properties.body.value;
  const responseType = node.properties.responseType?.value || 'auto';
  const authentication = node.properties.authentication?.value || 'none';
  const credentialId = node.properties.credentials?.value;

  helpers.log(`URL: ${url}`);
  helpers.log(`Method: ${method}`);
  helpers.log(`Response Type: ${responseType}`);

  // Build headers from fixedCollection
  const headers = {};
  const sendHeaders = node.properties.sendHeaders?.value;
  const headersCollection = node.properties.headersCollection?.value || [];

  if (sendHeaders && Array.isArray(headersCollection)) {
    helpers.log(`Processing ${headersCollection.length} custom header(s)`);
    for (const header of headersCollection) {
      if (header.key && header.value) {
        headers[header.key] = header.value;
        helpers.log(`Header: ${header.key} = ${header.value}`);
      }
    }
  }

  // Build query parameters from fixedCollection
  const sendQueryParams = node.properties.sendQueryParams?.value;
  const queryParamsCollection = node.properties.queryParams?.value || [];

  if (sendQueryParams && Array.isArray(queryParamsCollection) && queryParamsCollection.length > 0) {
    helpers.log(`Processing ${queryParamsCollection.length} query parameter(s)`);
    const urlObj = new URL(url);
    for (const param of queryParamsCollection) {
      if (param.key && param.value !== undefined && param.value !== null) {
        urlObj.searchParams.append(param.key, String(param.value));
        helpers.log(`Query param: ${param.key} = ${param.value}`);
      }
    }
    url = urlObj.toString();
    helpers.log(`Final URL with params: ${url}`);
  }

  if (authentication === 'apiKey' && credentialId && services) {
    try {
      helpers.log('Loading credentials...');
      const credentialDoc = await services.getDoc(services.doc(services.db, 'users', services.user.uid, 'credentials', credentialId));
      if (credentialDoc.exists()) {
        const credentialData = credentialDoc.data();
        const apiKey = credentialData?.data?.apiKey;
        if (apiKey) {
          headers['Authorization'] = `Bearer ${apiKey}`;
          helpers.log('Added API key to request headers');
        }
      } else {
        helpers.warn('Credential not found:', credentialId);
      }
    } catch (error) {
      helpers.error('Error loading credentials:', error);
    }
  }

  const bodyRaw = (method !== 'GET' && method !== 'DELETE') ? (typeof bodyValue === 'string' ? bodyValue : JSON.stringify(bodyValue || {})) : undefined;

  if (bodyRaw) {
    helpers.log(`Request body: ${bodyRaw.substring(0, 200)}${bodyRaw.length > 200 ? '...' : ''}`);
  }

  helpers.log('Sending request...');
  const response = await fetch(url, { method, headers, body: bodyRaw });

  const contentType = response.headers.get('content-type') || '';
  const contentDisposition = response.headers.get('content-disposition') || '';

  helpers.log(`Response status: ${response.status} ${response.statusText}`);
  helpers.log(`Content-Type: ${contentType}`);

  const isBinary = responseType === 'binary' || (responseType === 'auto' && (
    contentType.includes('application/octet-stream') ||
    contentType.includes('application/pdf') ||
    contentType.includes('application/zip') ||
    contentType.includes('application/gzip') ||
    contentType.includes('text/csv') ||
    contentType.includes('image/') ||
    contentType.includes('video/') ||
    contentType.includes('audio/') ||
    contentDisposition.includes('attachment')
  ));

  let responseData;

  if (isBinary) {
    helpers.log('Detected binary/file response');

    try {
      const blob = await response.blob();

      // Extract filename from Content-Disposition header
      let filename = `download_${Date.now()}`;
      if (contentDisposition) {
        // Use string methods instead of regex to avoid escaping issues
        const filenamePart = contentDisposition.split(';').find(part => part.includes('filename='));
        if (filenamePart) {
          filename = filenamePart.split('=')[1].replaceAll('"', '').replaceAll("'", '').trim();
        }
      }

      // Store file using NEW file-storage system (with user isolation)
      const fileRef = await helpers.storeFileFromBlob(blob, filename);

      responseData = {
        type: 'file',
        file: {
          id: fileRef.id,
          name: fileRef.name,
          mimeType: fileRef.mimeType,
          size: fileRef.size,
          sizeFormatted: fileRef.sizeFormatted
        }
      };
      helpers.log(`File stored with Firebase Storage: ${fileRef.name} (${fileRef.sizeFormatted})`);
    } catch (fileError) {
      helpers.error('Failed to store file:', fileError.message);
      helpers.warn('Falling back to base64 encoding');

      const buffer = await response.arrayBuffer();
      const base64 = Buffer.from(buffer).toString('base64');
      const sizeKB = (buffer.byteLength / 1024).toFixed(2);

      responseData = {
        type: 'binary',
        contentType: contentType,
        size: buffer.byteLength,
        sizeFormatted: `${sizeKB} KB`,
        base64: base64
      };
      helpers.log(`Received binary data: ${sizeKB} KB (base64 encoded)`);
    }
  } else if (responseType === 'text' || (responseType === 'auto' && !contentType.includes('application/json'))) {
    responseData = await response.text();
    helpers.log(`Received text response (${responseData.length} characters)`);
  } else {
    // Clone the response before consuming it, in case JSON parsing fails
    const clonedResponse = response.clone();
    try {
      responseData = await response.json();
      helpers.log('Received JSON response');
    } catch (e) {
      helpers.warn('Failed to parse as JSON, returning as text');
      responseData = await clonedResponse.text();
    }
  }

  helpers.log('HTTP Request completed successfully');

  return {
    status: response.status,
    statusText: response.statusText,
    data: responseData,
    headers: Object.fromEntries(response.headers.entries()),
    contentType: contentType
  };

} catch (error) {
  helpers.error('HTTP Request failed:', error.message);
  helpers.error('Stack trace:', error.stack);
  return {
    error: 'HTTP Request failed',
    message: error.message,
    stack: error.stack
  };
}
